id"><label>Dari<input name="origin" required placeholder="Jakarta"></label><label>Ke<input name="destination" required placeholder="Tokyo"></label></div><div class="mini-grid"><label>Berangkat<input type="datetime-local" name="departure_at" required></label><label>Tiba<input type="datetime-local" name="arrival_at"></label></div><div class="mini-grid"><label>DP wajib?<select name="dp_required"><option value="1">Ya</option><option value="0">Tidak</option></select></label><label>DP (%)<input type="number" name="dp_percent" value="50" min="0" max="100" required></label></div><label>Foto katalog<input type="file" name="product_image" accept="image/*"></label><label>Catatan perjalanan<textarea name="product_details" placeholder="Contoh: Bisa beli di Don Quijote, maksimal 3 kg."></textarea></label><label>Daftar produk</label><div id="product-list"><div class="product-row"><label>Nama<input name="products[0][name]" required placeholder="Nama barang"></label><label>Harga<input type="number" name="products[0][price]" min="0" required placeholder="Rp"></label><button type="button" class="remove-product" disabled><i class="bi bi-trash"></i></button><label style="grid-column:1/-1">Deskripsi<input name="products[0][description]" placeholder="Ukuran, warna, pilihan"></label></div></div><button type="button" class="btn btn-outline btn-sm" id="add-product"><i class="bi bi-plus-lg"></i> Tambah produk</button><button class="btn btn-primary" type="submit"><i class="bi bi-send"></i> Publikasikan jastip</button></form></section></div>
<script>
(()=>{const list=document.getElementById('product-list');const add=document.getElementById('add-product');let index=1;const update=()=>list.querySelectorAll('.remove-product').forEach(button=>button.disabled=list.children.length===1);add?.addEventListener('click',()=>{const row=document.createElement('div');row.className='product-row';row.innerHTML=`<label>Nama<input name="products[${index}][name]" required placeholder="Nama barang"></label><label>Harga<input type="number" name="products[${index}][price]" min="0" required placeholder="Rp"></label><button type="button" class="remove-product"><i class="bi bi-trash"></i></button><label style="grid-column:1/-1">Deskripsi<input name="products[${index}][description]" placeholder="Ukuran, warna, pilihan"></label>`;row.querySelector('.remove-product').addEventListener('click',()=>{row.remove();update();});list.appendChild(row);index++;update();});const poll=async()=>{try{const response=await fetch('{{ route('traveler.feed') }}',{headers:{Accept:'application/json'}});if(!response.ok)return;const data=await response.json();const badge=document.getElementById('pending-count');if(badge)badge.textContent=data.count;}catch(error){}};setInterval(poll,8000);})();
</script>
